from pathlib import Path
import json,argparse
from playwright.sync_api import sync_playwright,expect
ap=argparse.ArgumentParser();ap.add_argument('--baseline',action='store_true');args=ap.parse_args();OUT=Path(__file__).resolve().parent/'evidence'/('baseline' if args.baseline else 'current');OUT.mkdir(parents=True,exist_ok=True);URL='http://127.0.0.1:8765/pages/'
def go(p,page):p.goto(URL+page+'.html')
def setup(p):
 go(p,'m05-p01');p.evaluate('localStorage.setItem("dujia-prototype-works","[]");localStorage.setItem("dujia-prototype-records","[]");localStorage.setItem("dujia-prototype-moments","[]")')
